function send(response, status, contentType, body) {
  response.writeHead(status, { 'content-type': contentType, 'x-content-type-options': 'nosniff' });
  response.end(body);
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 10_000) throw new Error('Request body too large');
  }
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host ?? 'localhost'}`);
  if (request.method === 'GET' && url.pathname === '/health') {
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ status: 'ok' }));
    return;
  }

  if (request.method === 'GET' && url.pathname === '/api/directory') {
    const tasks = database.prepare(`
      SELECT p.id AS projectId, p.name AS projectName, p.archived,
        t.id AS taskId, t.title, t.completed, t.priority, t.due_date AS dueDate,
        t.notes, t.deleted
      FROM projects p
      JOIN task_project_positions position ON position.project_id = p.id
      JOIN tasks t ON t.id = position.task_id AND t.project_id = p.id
      ORDER BY p.id, position.position
    `).all().map((task) => ({
      ...task,
      archived: Boolean(task.archived),
      completed: Boolean(task.completed),
      deleted: Boolean(task.deleted),
      dueDate: task.dueDate ?? '',
      notes: task.notes ?? '',
    }));
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify(tasks));
    return;
  }

  if (request.method === 'POST' && url.pathname === '/api/directory/bulk-completion') {
    try {
      const payload = await readJson(request);
      if (typeof payload.completed !== 'boolean' || !Array.isArray(payload.taskIds)
        || payload.taskIds.some((id) => !Number.isSafeInteger(id) || id < 1)) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid bulk update' }));
        return;
      }
      const taskIds = [...new Set(payload.taskIds)];
      let changed = 0;
      database.exec('BEGIN IMMEDIATE');
      try {
        const update = database.prepare(`
          UPDATE tasks SET completed = ?
          WHERE id = ? AND deleted = 0 AND project_id IN (
            SELECT id FROM projects WHERE archived = 0
          )
        `);
        for (const taskId of taskIds) {
          changed += Number(update.run(payload.completed ? 1 : 0, taskId).changes);
        }
        database.exec('COMMIT');
      } catch (error) {
        database.exec('ROLLBACK');
        throw error;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ changed }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid bulk update' }));
    }
    return;
  }

  if (request.method === 'POST' && url.pathname === '/api/directory/bulk-deletion') {
    try {
      const payload = await readJson(request);
      if (typeof payload.deleted !== 'boolean' || !Array.isArray(payload.taskIds)
        || payload.taskIds.some((id) => !Number.isSafeInteger(id) || id < 1)) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid bulk update' }));
        return;
      }
      const taskIds = [...new Set(payload.taskIds)];
      let changed = 0;
      database.exec('BEGIN IMMEDIATE');
      try {
        const update = database.prepare(`
          UPDATE tasks SET deleted = ?
          WHERE id = ? AND deleted = ? AND project_id IN (
            SELECT id FROM projects WHERE archived = 0
          )
        `);
        for (const taskId of taskIds) {
          changed += Number(update.run(payload.deleted ? 1 : 0, taskId, payload.deleted ? 0 : 1).changes);
        }
        database.exec('COMMIT');
      } catch (error) {
        database.exec('ROLLBACK');
        throw error;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ changed }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid bulk update' }));
    }
    return;
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const filter = url.searchParams.get('filter') === 'Archived' ? 1 : 0;
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived, p.default_task_priority AS defaultTaskPriority,
        COUNT(CASE WHEN t.deleted = 0 THEN 1 END) AS totalCount,
        SUM(CASE WHEN t.deleted = 0 AND t.completed = 1 THEN 1 ELSE 0 END) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
    `).all(filter).map((project) => ({
      ...project,
      archived: Boolean(project.archived),
      totalCount: Number(project.totalCount),
      completedCount: Number(project.completedCount ?? 0),
    }));
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify(projects));
    return;
  }

  const projectExportRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/export$/);
  if (projectExportRoute && request.method === 'GET') {
    const projectId = Number(projectExportRoute[1]);
    const project = database.prepare(
      `SELECT name, archived, default_task_priority AS defaultPriority FROM projects WHERE id = ?`
    ).get(projectId);
    if (!project) {
      send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
      return;
    }
    const tasks = database.prepare(
      `SELECT t.title, t.completed, t.priority, t.due_date AS dueDate, t.notes, t.deleted
       FROM tasks t JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
       WHERE t.project_id = ? ORDER BY p.position`
    ).all(projectId).map((task) => ({
      title: task.title,
      completed: Boolean(task.completed),
      priority: task.priority ?? 'Normal',
      dueDate: task.dueDate ?? '',
      notes: (task.notes ?? '').replace(/\r\n?/g, '\n'),
      deleted: Boolean(task.deleted),
    }));
    const document = {
      format: 'workboard-project',
      version: 1,
      project: {
        name: project.name,
        archived: Boolean(project.archived),
        defaultPriority: project.defaultPriority ?? 'Normal',
        tasks,
      },
    };
    response.writeHead(200, {
      'content-type': 'application/json; charset=utf-8',
      'content-disposition': 'attachment; filename="workboard-project.json"',
      'x-content-type-options': 'nosniff',
    });
    response.end(JSON.stringify(document));
    return;
  }

  const projectDefaultRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/default-priority$/);
  if (projectDefaultRoute && request.method === 'PATCH') {
    try {
      const payload = await readJson(request);
      if (!['Low', 'Normal', 'High'].includes(payload.priority)) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid default task priority' }));
        return;
      }
      const result = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?')
        .run(payload.priority, Number(projectDefaultRoute[1]));
      if (result.changes === 0) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
        return;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ priority: payload.priority }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

